@require_POST
def email_tax_statement(request):
    statement_id = request.POST.get('statement_id')
    get_object_or_404(TaxStatement, id=statement_id, user=request.user)
    target_email = request.user.email
    send_tax_statement_pdf_task.delay(statement_id=statement_id, recipient=target_email)
    return JsonResponse({'message': 'Tax statement queued for delivery'})
